def problem_runtime(
    module: ModuleType, seed: int, backend: Backend | None = None
) -> ProblemRuntime:
    inputs = {}

    def make_inputs() -> CallInputs:
        nonlocal inputs

        kernel = cls(name or problem.name, problem, source_files)
