  const bf16* vhead = v + ((int64_t)b * kv_heads + kvh) * seq * kHeadDim;
  bf16* orow = out + (((int64_t)b * heads + h) * seq + qpos) * kHeadDim;

  const int* myids = ids + ((int64_t)(b * heads + h) * nblk + qblk) * cap;
  const int raw = counts[(int64_t)(b * heads + h) * nblk + qblk];
  const int cnt = raw < cap ? raw : cap;

  float m = -INFINITY;
  for (int pass = 0; pass < 3; ++pass) {
    if (pass == 0 || pass == 1) {
      float acc = (pass == 0) ? -INFINITY : 0.f;
      for (int s = 0; s < cnt; ++s) {
        const int bid = myids[s];
        if (bid < 0) continue;
        const int64_t base = (int64_t)bid * bs;
        if (base > qpos) continue;
        const bf16* kblk = khead + base * kHeadDim;
        const int lim = (int)(qpos - base) + 1;
        for (int off = 0; off < (lim < bs ? lim : bs); ++off) {
          const bf16* krow = kblk + (int64_t)off * kHeadDim;
          float dot = 0.f;
          for (int d = 0; d < kHeadDim; ++d)
            dot += (float)qrow[d] * (float)krow[d];
          dot *= scale;
          acc = (pass == 0) ? fmaxf(acc, dot) : acc + exp2f((dot - m) * kLog2e);
        }
      }
      if (pass == 0) {
        m = acc;
        if (!(m > -INFINITY)) {
