prims = '''
// ------------------------------------------------------------- wgmma (sm_90a)

// Shared-memory matrix descriptor: start address, leading (8-element k atom)
// byte stride, stride (8-row block) byte stride, no swizzle.
__device__ __forceinline__ uint64_t make_desc(uint32_t saddr, int lbo, int sbo) {
  uint64_t d = (uint64_t)((saddr >> 4) & 0x3FFF);
  d |= (uint64_t)((lbo >> 4) & 0x3FFF) << 16;
  d |= (uint64_t)((sbo >> 4) & 0x3FFF) << 32;
  return d;
}

__device__ __forceinline__ void wgmma_fence() {
  asm volatile(\"wgmma.fence.sync.aligned;\\\\n\");
}

__device__ __forceinline__ void wgmma_commit() {
  asm volatile(\"wgmma.commit_group.sync.aligned;\\\\n\");
}

__device__ __forceinline__ void wgmma_wait0() {
  asm volatile(\"wgmma.wait_group.sync.aligned 0;\\\\n\");
}

// S(64x128) += Q(64x128) @ K"'^T, A and B both read straight from shared memory.
__device__ __forceinline__ void wgmma_qk(float* d, uint64_t adesc, uint64_t bdesc) {
  asm volatile(
      "wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 "
      "{%s}, %%64, %%65, 1, 1, 1, 0, 0;'"\\\\n\"
      : %s
      : \"l\"(adesc), \"l\"(bdesc));
}

// K-major, no swizzle: 8 bf16 k-elements per 16-byte atom row, atoms stepped by
// the (bank-friendly) atom stride, 8-row blocks by the block stride.
__device__ __forceinline__ int km_ofs(int row, int chunk) {
  return (row >> 3) * (kBlkStride / 2) + chunk * (kAtomStride / 2) + (row & 7) * 8;
}

// Stage one 128x128 bf16 tile into the K-major layout: 2048 16-byte chunks.
__device__ __forceinline__ void load_tile_km(bf16* dst, const bf16* src, int tid) {
#pragma unroll
  for (int i = 0; i < 8; ++i) {
    const int idx = tid + (i << 8);
    cp_async16(dst + km_ofs(idx >> 4, idx & 15), src + idx * 8);
  }
}
''' % (acc, outs)

src = open('/tmp/p2.cu').read()

# 1. constants block
