constexpr int kRowStride = kBlockQ + kRowPad;
constexpr int kTileElems = kBlockQ * kRowStride;
constexpr int kTileBytes = kTileElems * 2;''',
'''constexpr int kRowPad = 8;                 // elements of padding per tile row
constexpr int kRowStride = kBlockQ + kRowPad;
constexpr int kTileElems = kBlockQ * kRowStride;
constexpr int kTileBytes = kTileElems * 2;

// wgmma operand tiles: 128 rows (n / m) x 128 dims (k), K-major, no swizzle.
// The 8-element k atoms sit kAtomStride bytes apart, which keeps both the
// cp.async writes and the tensor-core reads free of bank conflicts.
constexpr int kAtomStride = 144;
constexpr int kBlkStride = 16 * kAtomStride;   // 2304
constexpr int kKgStride = 2 * kAtomStride;     // one 16-element k step
constexpr int kKmTileBytes = 16 * kBlkStride;  // one 128x128 K-major tile
constexpr int kWgBytes = 8 * kBlkStride;       // one 64-row warpgroup tile''')

