131	// ------------------------------------------------------------------- kernels
132	
133	__global__ __launch_bounds__(kThreads)
134	void sparse_attn_fast(const bf16* __restrict__ q, const bf16* __restrict__ k,
135	                      const bf16* __restrict__ v, const int* __restrict__ ids,
136	                      const int* __restrict__ counts, bf16* __restrict__ out,
137	                      const int batch, const int heads, const int seq,
138	                      const int kv_heads, const int nblk, const int cap) {
139	#if KLINEAGE_TC
140	  extern __shared__ __align__(16) char smem[];
141	  bf16* qs = reinterpret_cast<bf16*>(smem);
142	  bf16* kbuf = qs + kTileElems;
143	  bf16* vbuf = kbuf + 2 * kTileElems;
144	
145	  __shared__ int s_ids[kCapMax];
146	  __shared__ int s_nslots;
147	
148	  const int tid = threadIdx.x;
149	  const int lane = tid & 31;
150	  const int warp = tid >> 5;
151	  const int row0 = warp * kRowsWarp;
152	  const int gid = lane >> 2;
153	  const int tg = lane & 3;
154	
155	  // Work unit: (batch, head, query block). Consecutive CTAs share a query
156	  // block, so the diagonal tile is fetched by up to `heads` CTAs at once.
157	  const int per_blk = batch * heads;
158	  const int qblk = nblk - 1 - blockIdx.x / per_blk;
159	  const int bh = blockIdx.x % per_blk;
160	  const int h = bh % heads;
161	  const int b = bh / heads;
162	  const int kvh = h / (heads / kv_heads);
163	
164	  // Compress the selected blocks: reversed order (nearest block first), -1 pads
165	  // and blocks past the query block dropped since every key they own is masked.
166	  if (tid == 0) {
167	    const int* myids = ids + ((size_t)bh * nblk + qblk) * cap;
168	    const int raw = counts[(size_t)bh * nblk + qblk];
169	    const int cnt = raw < cap ? raw : cap;
170	    int n = 0;
171	    for (int slot = cnt - 1; slot >= 0; --slot) {
172	      const int bid = myids[slot];
173	      if (bid < 0 || bid > qblk) continue;
174	      s_ids[n++] = bid;
175	    }
176	    s_nslots = n;
177	  }
178	  __syncthreads();
179	
180	  bf16* orow = out + (((size_t)b * heads + h) * seq + (size_t)qblk * kBlockQ +
181	                      row0 + gid) * kHeadDim;
182	  const int nslots = s_nslots;
183	  if (nslots == 0) {
184	#pragma unroll
185	    for (int nt = 0; nt < 16; ++nt) {
186	      const bf16x2 z = __floats2bfloat162_rn(0.f, 0.f);
187	      *reinterpret_cast<bf16x2*>(orow + nt * 8 + 2 * tg) = z;
188	      *reinterpret_cast<bf16x2*>(orow + 8 * kHeadDim + nt * 8 + 2 * tg) = z;
189	    }
190	    return;
191	  }
192	
193	  const bf16* ksrc = k + ((size_t)b * kv_heads + kvh) * seq * kHeadDim;
194	  const bf16* vsrc = v + ((size_t)b * kv_heads + kvh) * seq * kHeadDim;
195	  const bf16* qsrc =
196	      q + (((size_t)b * heads + h) * seq + (size_t)qblk * kBlockQ) * kHeadDim;
197	
198	  // Prologue: Q tile plus the first key/value tile, one commit group apart.
199	  load_tile(qs, qsrc, tid);
200	  cp_commit();
201	  load_tile(kbuf, ksrc + (size_t)s_ids[0] * kBlockQ * kHeadDim, tid);
202	  load_tile(vbuf, vsrc + (size_t)s_ids[0] * kBlockQ * kHeadDim, tid);
203	  cp_commit();
204	  cp_wait<1>();
205	  __syncthreads();
206	
207	  const int lr_q = (lane & 7) + ((lane & 8) ? 8 : 0);
208	  const int lc_q = (lane >> 4) & 1;
209	
210	  float o[16][4];
211	#pragma unroll
212	  for (int nt = 0; nt < 16; ++nt)
213	#pragma unroll
214	    for (int j = 0; j < 4; ++j) o[nt][j] = 0.f;
215	  float mrow[2] = {kMasked, kMasked};
216	  float lrow[2] = {0.f, 0.f};
217	
218	  const int lr_k = (lane & 7) + ((lane & 16) ? 8 : 0);
219	  const int lc_k = (lane >> 3) & 1;
220	  const int lr_v = (lane & 7) + ((lane & 8) ? 8 : 0);
221	  const int lc_v = (lane >> 4) & 1;
222	
223	  // Per-thread smem bases. Every ldmatrix address below is base + constant, so
224	  // ptxas folds the whole swizzle arithmetic into the load's immediate offset.
225	  const int q_off = tile_ofs(row0 + lr_q, lc_q);
226	  const int k_off = tile_ofs(lr_k, lc_k);
227	  const int v_off = tile_ofs(lr_v, lc_v);
228	  const int qrow_a = row0 + gid;
229	  const int qrow_b = qrow_a + 8;
230	
231	  for (int slot = 0; slot < nslots; ++slot) {
232	    const int bid = s_ids[slot];
233	    const bf16* kcur = kbuf + (slot & 1) * kTileElems;
234	    const bf16* vcur = vbuf + (slot & 1) * kTileElems;
235	
236	    if (slot + 1 < nslots) {
237	      const size_t off = (size_t)s_ids[slot + 1] * kBlockQ * kHeadDim;
238	      load_tile(kbuf + ((slot + 1) & 1) * kTileElems, ksrc + off, tid);
239	      load_tile(vbuf + ((slot + 1) & 1) * kTileElems, vsrc + off, tid);
240	      cp_commit();
241	      cp_wait<1>();
242	    } else {
243	      cp_wait<0>();
244	    }
245	    __syncthreads();
246	
247	    // The diagonal block is causal: a warp stops at the last chunk its rows can
248	    // reach, and only that chunk can hold masked keys.
249	    const bool causal = (bid == qblk);
250	    const int reach = (row0 + kRowsWarp + kChunkKeys - 1) / kChunkKeys;
251	    const int chn = causal && reach < kChunks ? reach : kChunks;
252	
253	    for (int ch = 0; ch < chn; ++ch) {
254	      const int key_base = ch * kChunkKeys;
255	    const int krow_off = key_base * kRowStride;
256	      float s[kNtPerChunk][4];
257	#pragma unroll
258	      for (int nt = 0; nt < kNtPerChunk; ++nt) {
259	        s[nt][0] = 0.f;
260	        s[nt][1] = 0.f;
261	        s[nt][2] = 0.f;
262	        s[nt][3] = 0.f;
263	      }
264	
265	      // S = Q @ K^T for 16 rows x kChunkKeys keys.
266	#pragma unroll
267	      for (int ks = 0; ks < 8; ++ks) {
268	        uint32_t qa[4];
269	        ldsm_x4(qa[0], qa[1], qa[2], qa[3],
270	                qs + (q_off + ks * 16));
271	#pragma unroll
272	        for (int kg = 0; kg < kKgPerChunk; ++kg) {
273	          uint32_t b0, b1, b2, b3;
274	          ldsm_x4(b0, b1, b2, b3,
275	                  kcur + (k_off + krow_off + kg * (16 * kRowStride) + ks * 16));
276	          mma16816(s[kg * 2], qa, b0, b1);
277	          mma16816(s[kg * 2 + 1], qa, b2, b3);
278	        }
279	      }
280	
281	      if (causal && ch == row0 / kChunkKeys) {
282	#pragma unroll
283	        for (int nt = 0; nt < kNtPerChunk; ++nt) {
284	          const int kb = key_base + nt * 8 + 2 * tg;
285	          if (kb > qrow_a) s[nt][0] = kMasked;
286	          if (kb + 1 > qrow_a) s[nt][1] = kMasked;
287	          if (kb > qrow_b) s[nt][2] = kMasked;
288	          if (kb + 1 > qrow_b) s[nt][3] = kMasked;
289	        }
290	      }
291	
292	      // Online softmax over this chunk.
293	      float mx0 = fmaxf(s[0][0], s[0][1]);
294	      float mx1 = fmaxf(s[0][2], s[0][3]);
295	#pragma unroll
296	      for (int nt = 1; nt < kNtPerChunk; ++nt) {
297	        mx0 = fmaxf(mx0, fmaxf(s[nt][0], s[nt][1]));
298	        mx1 = fmaxf(mx1, fmaxf(s[nt][2], s[nt][3]));
299	      }
300	      const float mnew0 = fmaxf(mrow[0], warp_max(mx0));
301	      const float mnew1 = fmaxf(mrow[1], warp_max(mx1));
302	      const float a0 = exp2f((mrow[0] - mnew0) * kExpScale);
303	      const float a1 = exp2f((mrow[1] - mnew1) * kExpScale);
304	#pragma unroll
305	      for (int nt = 0; nt < 16; ++nt) {
306	        o[nt][0] *= a0;
307	        o[nt][1] *= a0;
308	        o[nt][2] *= a1;
309	        o[nt][3] *= a1;
310	      }
311	
312	      float p0 = 0.f;
313	      float p1 = 0.f;
314	#pragma unroll
315	      for (int nt = 0; nt < kNtPerChunk; ++nt) {
316	        s[nt][0] = exp2f((s[nt][0] - mnew0) * kExpScale);
317	        s[nt][1] = exp2f((s[nt][1] - mnew0) * kExpScale);
318	        s[nt][2] = exp2f((s[nt][2] - mnew1) * kExpScale);
319	        s[nt][3] = exp2f((s[nt][3] - mnew1) * kExpScale);
320	        p0 += s[nt][0] + s[nt][1];
321	        p1 += s[nt][2] + s[nt][3];
322	      }
323	      lrow[0] = lrow[0] * a0 + warp_sum(p0);
324	      lrow[1] = lrow[1] * a1 + warp_sum(p1);
325	      mrow[0] = mnew0;
326	      mrow[1] = mnew1;
327	
328	      // O += P @ V, with P taken straight from the score fragments.
329	#pragma unroll
330	      for (int kk = 0; kk < kKgPerChunk; ++kk) {
331	        const uint32_t pa[4] = {pack2(s[2 * kk][0], s[2 * kk][1]),
332	                                pack2(s[2 * kk][2], s[2 * kk][3]),
333	                                pack2(s[2 * kk + 1][0], s[2 * kk + 1][1]),
334	                                pack2(s[2 * kk + 1][2], s[2 * kk + 1][3])};
335	#pragma unroll
336	        for (int dg = 0; dg < 8; ++dg) {
337	          uint32_t b0, b1, b2, b3;
338	          ldsm_x4_t(b0, b1, b2, b3,
339	                    vcur + (v_off + krow_off + kk * (16 * kRowStride) + dg * 16));
340	          mma16816(o[2 * dg], pa, b0, b1);
341	          mma16816(o[2 * dg + 1], pa, b2, b3);
342	        }
343	      }
344	    }
345	    __syncthreads();
346	  }
347	
348	  const float inv0 = lrow[0] > 0.f ? 1.f / lrow[0] : 0.f;
349	  const float inv1 = lrow[1] > 0.f ? 1.f / lrow[1] : 0.f;
350	#pragma unroll
351	  for (int nt = 0; nt < 16; ++nt) {
352	    *reinterpret_cast<bf16x2*>(orow + nt * 8 + 2 * tg) =
353	        __floats2bfloat162_rn(o[nt][0] * inv0, o[nt][1] * inv0);
354	    *reinterpret_cast<bf16x2*>(orow + 8 * kHeadDim + nt * 8 + 2 * tg) =
355	        __floats2bfloat162_rn(o[nt][2] * inv1, o[nt][3] * inv1);
356	  }
357	#endif  // KLINEAGE_TC
358	}
359	
360	
361	// One thread per query row, three passes (max, sum, weighted value). Correct
362	// for any head dimension and any query block size; fallback only.
363	struct NaiveCtx {
364	  const bf16* qrow;
365	  const bf16* khead;
366	  const bf16* vhead;
367	  const int* myids;
368	  int cnt;
369	  int bs;
370	  int64_t qpos;
371	  float scale;
372	
373	  __device__ __forceinline__ float dot(const bf16* krow) const {
374	    float acc = 0.f;
375	    for (int d = 0; d < kHeadDim; ++d)
376	      acc += __bfloat162float(qrow[d]) * __bfloat162float(krow[d]);
377	    return acc * scale;
378	  }
379	
380	  template <typename Fn>
381	  __device__ __forceinline__ void each_key(Fn&& fn) const {
382	    for (int s = 0; s < cnt; ++s) {
383	      const int bid = myids[s];
384	      if (bid < 0) continue;
385	      const int64_t base = (int64_t)bid * bs;
386	      if (base > qpos) continue;
387	      const int lim = (int)(qpos - base) + 1;
388	      const int n = lim < bs ? lim : bs;
389	      for (int off = 0; off < n; ++off) {
390	        fn(khead + (base + off) * kHeadDim, vhead + (base + off) * kHeadDim);
391	      }
392	    }
393	  }
394	};
395	
396	__global__ void sparse_attn_naive(const bf16* __restrict__ q,
397	                                  const bf16* __restrict__ k,
398	                                  const bf16* __restrict__ v,
399	                                  const int* __restrict__ ids,
400	                                  const int* __restrict__ counts,
401	                                  bf16* __restrict__ out, const int batch,
402	                                  const int heads, const int seq,
403	                                  const int kv_heads, const int nblk,
404	                                  const int cap, const float scale) {
405	  const int bs = seq / nblk;
406	  const int64_t total = (int64_t)batch * heads * nblk * bs;
407	  const int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
408	  if (idx >= total) return;
409	
410	  const int r = (int)(idx % bs);
411	  const int qblk = (int)(idx / bs % nblk);
412	  const int h = (int)(idx / ((int64_t)bs * nblk) % heads);
413	  const int b = (int)(idx / ((int64_t)bs * nblk * heads));
414	  const int kvh = h / (heads / kv_heads);
415	  const int64_t qpos = (int64_t)qblk * bs + r;
416	
417	  const int* myids = ids + ((int64_t)(b * heads + h) * nblk + qblk) * cap;
418	  const int raw = counts[(int64_t)(b * heads + h) * nblk + qblk];
419	  NaiveCtx ctx{(const bf16*)(q + (((int64_t)b * heads + h) * seq + qpos) * kHeadDim),
420	               k + ((int64_t)b * kv_heads + kvh) * seq * kHeadDim,
421	               v + ((int64_t)b * kv_heads + kvh) * seq * kHeadDim,
422	               myids,
423	               raw < cap ? raw : cap,
424	               bs,
425	               qpos,
426	               scale};
427	  bf16* orow = out + (((int64_t)b * heads + h) * seq + qpos) * kHeadDim;
428	
429	  float m = -INFINITY;
430	  ctx.each_key([&](const bf16* krow, const bf16* vrow) { m = fmaxf(m, ctx.dot(krow)); });
431	  if (!(m > -INFINITY)) {
432	    for (int d = 0; d < kHeadDim; ++d) orow[d] = __float2bfloat16(0.f);
433	    return;
434	  }
435	
436	  float l = 0.f;
437	  ctx.each_key([&](const bf16* krow, const bf16* vrow) {
438	    l += exp2f((ctx.dot(krow) - m) * kLog2e);
439	  });
440	  const float inv = l > 0.f ? 1.f / l : 0.f;
441	
442	  for (int d = 0; d < kHeadDim; ++d) {
443	    float acc = 0.f;
444	    ctx.each_key([&](const bf16* krow, const bf16* vrow) {
445	      acc += exp2f((ctx.dot(krow) - m) * kLog2e) * __bfloat162float(vrow[d]);
446	    });
447	    orow[d] = __float2bfloat16(acc * inv);
448	  }
449	}
