452	
453	void check_common(const torch::Tensor& t, torch::ScalarType dtype, const char* name) {
454	  TORCH_CHECK(t.is_cuda(), name, " must be a CUDA tensor");
455	  TORCH_CHECK(t.scalar_type() == dtype, name, " has the wrong dtype");
456	  TORCH_CHECK(t.is_contiguous(), name, " must be contiguous");
457	}
458	
459	void kernel(const torch::Tensor& q, const torch::Tensor& k, const torch::Tensor& v,
460	            const torch::Tensor& block_ids, const torch::Tensor& block_counts,
461	            torch::Tensor& out) {
462	  check_common(q, torch::kBFloat16, "q");
463	  check_common(k, torch::kBFloat16, "k");
464	  check_common(v, torch::kBFloat16, "v");
465	  check_common(out, torch::kBFloat16, "out");
466	  check_common(block_ids, torch::kInt32, "block_ids");
467	  check_common(block_counts, torch::kInt32, "block_counts");
468	  TORCH_CHECK(q.dim() == 4 && k.dim() == 4 && v.dim() == 4 && out.dim() == 4,
469	              "q/k/v/out must be rank 4");
470	  TORCH_CHECK(block_ids.dim() == 4 && block_counts.dim() == 3,
471	              "block_ids/block_counts have the wrong rank");
472	
473	  const int64_t batch = q.size(0);
474	  const int64_t heads = q.size(1);
475	  const int64_t seq = q.size(2);
476	  const int64_t dim = q.size(3);
477	  const int64_t kv_heads = k.size(1);
478	  const int64_t nblk = block_ids.size(2);
479	  const int64_t cap = block_ids.size(3);
480	  TORCH_CHECK(dim == kHeadDim && k.size(3) == kHeadDim && v.size(3) == kHeadDim,
481	              "head dimension must be ", kHeadDim);
482	  TORCH_CHECK(k.size(0) == batch && k.size(2) == seq && v.size(0) == batch &&
483	                  v.size(1) == kv_heads && v.size(2) == seq,
484	              "k/v shapes must match q");
485	  TORCH_CHECK(out.sizes() == q.sizes(), "out must match q");
486	  TORCH_CHECK(block_ids.size(0) == batch && block_ids.size(1) == heads &&
487	                  block_counts.size(0) == batch && block_counts.size(1) == heads &&
488	                  block_counts.size(2) == nblk,
489	              "block_ids/block_counts must match q");
490	  TORCH_CHECK(heads % kv_heads == 0, "heads must be a multiple of kv heads");
491	  TORCH_CHECK(seq % nblk == 0, "sequence must divide evenly into blocks");
492	  TORCH_CHECK(cap >= 1 && cap <= kCapMax, "block capacity must be in [1, ", kCapMax, "]");
493	
494	  if (batch == 0 || heads == 0 || seq == 0) return;
495	
496	  c10::cuda::CUDAGuard guard(q.device());
497	  const cudaStream_t stream =
498	      c10::cuda::getCurrentCUDAStream(q.get_device()).stream();
499	
500	  const bf16* qp = reinterpret_cast<const bf16*>(q.data_ptr<at::BFloat16>());
501	  const bf16* kp = reinterpret_cast<const bf16*>(k.data_ptr<at::BFloat16>());
502	  const bf16* vp = reinterpret_cast<const bf16*>(v.data_ptr<at::BFloat16>());
503	  bf16* op = reinterpret_cast<bf16*>(out.data_ptr<at::BFloat16>());
504	  const int* idp = block_ids.data_ptr<int>();
505	  const int* ctp = block_counts.data_ptr<int>();
506	
507	  if (seq / nblk == kBlockQ) {
508	    const int smem_bytes = (1 + 4) * kTileBytes;
509	    static bool configured = false;
510	    if (!configured) {
511	      cudaFuncSetAttribute(sparse_attn_fast, cudaFuncAttributeMaxDynamicSharedMemorySize,
512	                           smem_bytes);
513	      configured = true;
514	    }
515	    const int grid = (int)(batch * heads * nblk);
516	    sparse_attn_fast<<<grid, kThreads, smem_bytes, stream>>>(
517	        qp, kp, vp, idp, ctp, op, (int)batch, (int)heads, (int)seq, (int)kv_heads,
518	        (int)nblk, (int)cap);
519	  } else {
520	    const int64_t total = batch * heads * seq;
521	    const int threads = 128;
522	    const int grid = (int)((total + threads - 1) / threads);
