1	// Causal block-sparse attention: gather the selected key blocks, apply ordinary
2	// masked attention (FlashAttention-2 style) over the compressed key list.
3	//
4	//   queries per block : 128          (block_ids.shape[-2] == S / 128)
5	//   head dimension    : 128
6	//   key blocks        : up to `cap` ids taken from block_ids, -1 pads
7	//   diagonal block    : causal; strictly earlier blocks are fully visible
8	//   keys from padded slots or from blocks beyond the query block are dead
9	//
10	// Fast path: one CTA per (batch, head, query block), 8 warps x 16 rows each,
11	// 128x128 bf16 tiles in shared memory, mma.m16n8k16 tensor-core math.
12	#include <torch/extension.h>
13	#include <c10/cuda/CUDAGuard.h>
14	#include <c10/cuda/CUDAStream.h>
15	#include <cuda_runtime.h>
16	#include <cuda_bf16.h>
17	#include <cstdint>
18	
19	namespace {
20	
21	using bf16 = __nv_bfloat16;
22	using bf16x2 = __nv_bfloat162;
23	
24	constexpr int kHeadDim = 128;    // head dimension handled by the fast kernel
25	constexpr int kBlockQ = 128;     // queries per query block
26	constexpr int kWarps = 8;
27	constexpr int kThreads = kWarps * 32;
28	constexpr int kRowsWarp = kBlockQ / kWarps;  // 16
29	constexpr int kChunkKeys = 128;              // keys per online-softmax step
30	constexpr int kChunks = kBlockQ / kChunkKeys;
31	constexpr int kKgPerChunk = kChunkKeys / 16;   // 16-key mma groups per chunk
32	constexpr int kNtPerChunk = kChunkKeys / 8;    // 8-key score tiles per chunk
33	constexpr int kCapMax = 64;                  // largest block_ids capacity honored
34	constexpr int kRowPad = 8;                 // elements of padding per tile row
35	constexpr int kRowStride = kBlockQ + kRowPad;
36	constexpr int kTileElems = kBlockQ * kRowStride;
37	constexpr int kTileBytes = kTileElems * 2;
38	
39	// wgmma operands: 128 x 128 bf16 tiles, K-major, no swizzle. The 8-element k
40	// atoms sit kAtomStride bytes apart, which keeps cp.async writes and tensor-core
41	// reads free of bank conflicts.
42	constexpr int kAtomStride = 144;
43	constexpr int kBlkStride = 16 * kAtomStride;   // 8-row block stride, 2304 B
44	constexpr int kKgStride = 2 * kAtomStride;     // one 16-element k step, 288 B
45	constexpr int kKmTileBytes = 16 * kBlkStride;  // one 128x128 K-major tile
46	constexpr int kWgBytes = 8 * kBlkStride;       // one 64-row warpgroup tile
47	constexpr int kSmemBytes = kKmTileBytes * 3 + kTileBytes * 2;
48	constexpr float kLog2e = 1.4426950408889634f;
49	// 1/sqrt(128); folded into the exp2 argument so the softmax runs on raw dots.
50	constexpr float kScoreScale = 0.08838834764831845f;
51	constexpr float kExpScale = kScoreScale * kLog2e;
52	constexpr float kMasked = -1.0e30f;
53	
54	// bf16 mma needs sm_80; older targets keep only the scalar fallback. The host
55	// pass sees an undefined __CUDA_ARCH__ and keeps the tensor-core path.
56	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ < 800)
57	#define KLINEAGE_TC 0
58	#else
59	#define KLINEAGE_TC 1
60	#endif
61	
62	// wgmma lives in the sm_90a feature set only; every other target keeps the mma
63	// path, so a fat binary without sm_90a still computes the right answer.
64	#if defined(__CUDA_ARCH__) && defined(__CUDA_ARCH_FEAT_SM90_ALL)
65	#define KLINEAGE_WG 1
66	#else
67	#define KLINEAGE_WG 0
68	#endif
