73	
74	// 128x128 bf16 tile padded to a 136-element (272 B) row stride. Row r starts at
75	// bank 4r, so the eight rows of an ldmatrix tile cover all 32 banks with no
76	// conflict, and every tile address stays affine in the row/column indices.
77	// (row, chunk) -> element offset, chunk in 16-byte (8 element) units.
78	__device__ __forceinline__ int tile_ofs(int row, int chunk) {
79	  return row * kRowStride + chunk * 8;
80	}
