82	__device__ __forceinline__ void cp_async16(void* dst, const void* src) {
83	  const uint32_t s = (uint32_t)__cvta_generic_to_shared(dst);
84	  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::"r"(s), "l"(src));
85	}
86	
87	__device__ __forceinline__ void cp_commit() { asm volatile("cp.async.commit_group;\n"); }
88	
89	template <int N>
90	__device__ __forceinline__ void cp_wait() {
91	  asm volatile("cp.async.wait_group %0;\n" ::"n"(N));
92	}
