94	// Stage one 128x128 bf16 tile: 2048 chunks of 16 bytes, 8 per thread.
95	__device__ __forceinline__ void load_tile(bf16* dst, const bf16* src, int tid) {
96	  const bf16* base = src;
97	  bf16* dbase = dst;
98	#pragma unroll
99	  for (int i = 0; i < 8; ++i) {
100	    const int idx = tid + (i << 8);
101	    cp_async16(dbase + tile_ofs(idx >> 4, idx & 15), base + idx * 8);
102	  }
103	}
