105	__device__ __forceinline__ void ldsm_x4(uint32_t& r0, uint32_t& r1, uint32_t& r2,
106	                                        uint32_t& r3, const bf16* p) {
107	  const uint32_t a = (uint32_t)__cvta_generic_to_shared(p);
108	  asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
109	               : "=r"(r0), "=r"(r1), "=r"(r2), "=r"(r3)
110	               : "r"(a));
111	}
