113	__device__ __forceinline__ void ldsm_x4_t(uint32_t& r0, uint32_t& r1, uint32_t& r2,
114	                                          uint32_t& r3, const bf16* p) {
115	  const uint32_t a = (uint32_t)__cvta_generic_to_shared(p);
116	  asm volatile(
117	      "ldmatrix.sync.aligned.m8n8.x4.trans.shared.b16 {%0,%1,%2,%3}, [%4];\n"
118	      : "=r"(r0), "=r"(r1), "=r"(r2), "=r"(r3)
119	      : "r"(a));
120	}

