132	// 128x128 bf16 tile, K-major, no swizzle: an atom is 8 rows x 16 bytes with the
133	// rows contiguous, atoms step by kAtomStride along k and 8-row blocks by
134	// kBlkStride along the n/m dimension. Descriptor = start | lbo | sbo.
135	__device__ __forceinline__ uint64_t make_desc(uint32_t saddr, int lbo, int sbo) {
136	  uint64_t d = (uint64_t)((saddr >> 4) & 0x3FFF);
137	  d |= (uint64_t)((lbo >> 4) & 0x3FFF) << 16;
138	  d |= (uint64_t)((sbo >> 4) & 0x3FFF) << 32;
139	  return d;
140	}
