  const bf16* kp = reinterpret_cast<const bf16*>(k.data_ptr<at::BFloat16>());
  const bf16* vp = reinterpret_cast<const bf16*>(v.data_ptr<at::BFloat16>());
  bf16* op = reinterpret_cast<bf16*>(out.data_ptr<at::BFloat16>());
