@torch.no_grad()
def run(q, k, v, block_ids, block_counts):
    """Gather the supplied blocks, then apply ordinary masked attention."""
    batch, heads, sequence, width = q.shape
    query_blocks, capacity = block_ids.shape[-2:]
    block_size = sequence // query_blocks
    groups = heads // k.shape[1]
    offsets = torch.arange(block_size, device=q.device)
    slots = torch.arange(capacity, device=q.device)
    head_map = torch.arange(heads, device=q.device) // groups
    keys = k.float().index_select(1, head_map)
    values = v.float().index_select(1, head_map)
    out = torch.empty_like(q)

    # Keep scores local to one query block to bound reference memory.
    for block in range(query_blocks):
        start = block * block_size
        ids = block_ids[:, :, block].long()
        counts = block_counts[:, :, block]
        tokens = (ids[..., None] * block_size + offsets).flatten(-2)
        active = (slots < counts[..., None]).repeat_interleave(block_size, -1)
        gather = tokens.clamp_min(0)[..., None].expand(-1, -1, -1, width)
        kb = torch.gather(keys, 2, gather)
        vb = torch.gather(values, 2, gather)
        qb = q[:, :, start : start + block_size].float()
        positions = start + offsets
        allowed = active[..., None, :] & (tokens[..., None, :] <= positions[:, None])

        scores = torch.matmul(qb, kb.transpose(-2, -1)) / math.sqrt(width)
        scores.masked_fill_(~allowed, -torch.inf)
        weights = torch.softmax(scores, dim=-1)
        out[:, :, start : start + block_size] = torch.matmul(weights, vb).to(q.dtype)

    return out
