      float p1 = 0.f;
#pragma unroll
      for (int nt = 0; nt < kNtPerChunk; ++nt) {
        s[rt][nt][0] = fast_exp2(fmaf(s[rt][nt][0], kExpScale, t0));
        s[rt][nt][1] = fast_exp2(fmaf(s[rt][nt][1], kExpScale, t0));
        s[rt][nt][2] = fast_exp2(fmaf(s[rt][nt][2], kExpScale, t1));
        s[rt][nt][3] = fast_exp2(fmaf(s[rt][nt][3], kExpScale, t1));
