        pa[rt][0] = pack2(s[rt][2 * kk][0], s[rt][2 * kk][1]);
        pa[rt][1] = pack2(s[rt][2 * kk][2], s[rt][2 * kk][3]);
        pa[rt][2] = pack2(s[rt][2 * kk + 1][0], s[rt][2 * kk + 1][1]);
