  for (int rt = 0; rt < kNRowS; ++rt) {
    const float inv0 = lrow[rt][0] > 0.f ? 1.f / lrow[rt][0] : 0.f;
    const float inv1 = lrow[rt][1] > 0.f ? 1.f / lrow[rt][1] : 0.f;
